import (
	"errors"
	"fmt"
)

// Product is a palindromic number along with the factor pairs
// (within the given range) that produce it.
type Product struct {
	Value          int
	Factorizations [][2]int
}

// Products finds the smallest and largest palindromes that are the product
// of two numbers within the range [fmin, fmax], along with all factor pairs
// within the range that produce each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var min, max Product
	for a := fmin; a <= fmax; a++ {
		for b := a; b <= fmax; b++ { // b >= a avoids duplicate pairs
			value := a * b
			if !isPalindrome(value) {
				continue
			}
			if max.Value < value || len(max.Factorizations) == 0 {
				max = Product{Value: value, Factorizations: [][2]int{{a, b}}}
			} else if max.Value == value {
				max.Factorizations = append(max.Factorizations, [2]int{a, b})
			}
			if min.Value > value || len(min.Factorizations) == 0 {
				min = Product{Value: value, Factorizations: [][2]int{{a, b}}}
			} else if min.Value == value {
				min.Factorizations = append(min.Factorizations, [2]int{a, b})
			}
		}
	}

	if len(min.Factorizations) == 0 {
		return Product{}, Product{},
			fmt.Errorf("no palindromes found in range [%d, %d]", fmin, fmax)
	}

	return min, max, nil
}

// isPalindrome reports whether the decimal representation of n
// reads the same forwards and backwards.
func isPalindrome(n int) bool {
	s := fmt.Sprintf("%d", n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}
